{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE eggozdb.maplemonk.my_sql_COCO_DATA AS WITH base_orders AS ( SELECT oc1.customer_id, oc1.retailer_id, rc.phone_no, rr.retailer_type, DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) AS order_month, CAST( TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS DATE ) AS order_date FROM eggozdb.maplemonk.my_sql_order_cmsorder oc1 LEFT JOIN eggozdb.maplemonk.my_sql_retailer_cmscustomer rc ON oc1.customer_id = rc.id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON oc1.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' ), customer_cohort AS ( SELECT customer_id, retailer_id, phone_no, MIN(order_month) AS cohort_month FROM base_orders GROUP BY customer_id, retailer_id, phone_no ), cohort_size AS ( SELECT cohort_month, retailer_id, COUNT(DISTINCT customer_id) AS cohort_customers FROM customer_cohort GROUP BY cohort_month, retailer_id ), retention_calc AS ( SELECT cc.cohort_month, cc.retailer_id, DATEDIFF( MONTH, cc.cohort_month, bo.order_month ) AS month_number, TO_CHAR(bo.order_month, \'Mon YYYY\') AS month_name, COUNT(DISTINCT cc.customer_id) AS retained_customers FROM customer_cohort cc LEFT JOIN base_orders bo ON cc.customer_id = bo.customer_id AND cc.retailer_id = bo.retailer_id GROUP BY cc.cohort_month, cc.retailer_id, DATEDIFF( MONTH, cc.cohort_month, bo.order_month ), TO_CHAR(bo.order_month, \'Mon YYYY\') ), final_retention AS ( SELECT r.cohort_month, r.retailer_id, r.month_number, r.month_name, r.retained_customers, cs.cohort_customers, ROUND( r.retained_customers * 100.0 / NULLIF(cs.cohort_customers, 0), 2 ) AS retention_rate FROM retention_calc r LEFT JOIN cohort_size cs ON r.cohort_month = cs.cohort_month AND r.retailer_id = cs.retailer_id ), monthly_customer_orders AS ( SELECT customer_id, retailer_id, DATE_TRUNC( \'MONTH\', order_date ) AS reporting_month, MAX(order_date) AS last_order_in_month FROM base_orders GROUP BY customer_id, retailer_id, DATE_TRUNC( \'MONTH\', order_date ) ), monthly_churn AS ( SELECT customer_id, retailer_id, reporting_month, last_order_in_month, LEAD(last_order_in_month) OVER ( PARTITION BY customer_id, retailer_id ORDER BY reporting_month ) AS next_order_date, DATEDIFF( DAY, last_order_in_month, LEAD(last_order_in_month) OVER ( PARTITION BY customer_id, retailer_id ORDER BY reporting_month ) ) AS days_between_orders, CASE WHEN LEAD(last_order_in_month) OVER ( PARTITION BY customer_id, retailer_id ORDER BY reporting_month ) IS NULL THEN \'Yes\' WHEN DATEDIFF( DAY, last_order_in_month, LEAD(last_order_in_month) OVER ( PARTITION BY customer_id, retailer_id ORDER BY reporting_month ) ) BETWEEN 31 AND 89 THEN \'Yes\' ELSE \'No\' END AS churn_gt_30_lt_90_days, CASE WHEN DATEDIFF( DAY, last_order_in_month, LEAD(last_order_in_month) OVER ( PARTITION BY customer_id, retailer_id ORDER BY reporting_month ) ) >= 90 THEN \'Yes\' ELSE \'No\' END AS churn_gt_90_days FROM monthly_customer_orders ), monthly_churn_pct AS ( SELECT reporting_month, retailer_id, COUNT(DISTINCT CASE WHEN churn_gt_30_lt_90_days = \'Yes\' THEN customer_id END) AS churned_customers_30_90, COUNT(DISTINCT CASE WHEN churn_gt_90_days = \'Yes\' THEN customer_id END) AS churned_customers_90_plus, COUNT(DISTINCT customer_id) AS total_customers, ROUND( COUNT(DISTINCT CASE WHEN churn_gt_30_lt_90_days = \'Yes\' THEN customer_id END) * 100.0 / NULLIF(COUNT(DISTINCT customer_id), 0), 2 ) AS churn_pct_30_90, ROUND( COUNT(DISTINCT CASE WHEN churn_gt_90_days = \'Yes\' THEN customer_id END) * 100.0 / NULLIF(COUNT(DISTINCT customer_id), 0), 2 ) AS churn_pct_90_plus FROM monthly_churn GROUP BY reporting_month, retailer_id ), customer_egg_type AS ( SELECT o.customer_id, o.retailer_id, DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, o.created_at) ) AS order_month, CASE WHEN MAX( CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%HG%\' THEN \'Bread\' END ) = \'Bread\' THEN \'Bread\' WHEN COUNT(DISTINCT CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%B%\' THEN \'White\' END ) > 1 THEN \'Mixed\' WHEN MAX( CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' END ) = \'Brown\' THEN \'Brown\' WHEN MAX( CASE WHEN UPPER(CONCAT(p.sku_count, p.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(p.sku_count, p.short_name)) NOT LIKE \'%B%\' THEN \'White\' END ) = \'White\' THEN \'White\' ELSE \'Mixed\' END AS customer_product_type FROM eggozdb.maplemonk.my_sql_order_cmsorder o LEFT JOIN eggozdb.maplemonk.my_sql_order_cmsorderline ol ON ol.cms_order_id = o.id LEFT JOIN eggozdb.maplemonk.my_sql_product_product p ON p.id = ol.product_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON o.retailer_id = rr.id WHERE rr.retailer_type = \'Coco\' GROUP BY o.customer_id, o.retailer_id, DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, o.created_at) ) ) SELECT oc1.customer_id, oc1.retailer_id, rr.billing_name_of_shop, oc.mrp, oc.quantity * oc.mrp AS MRP_VALUE, oc.quantity, oc.single_sku_rate, oc1.total_amount, oc.single_sku_rate * oc.quantity AS sku_value, oc1.discount_amount, oc1.discount_id, oc1.referral_source, rc.name, rc.phone_no, oc1.id, CONCAT(\'ord-\', oc1.id) AS \"Invoice No\", CONCAT(pp.sku_count, pp.short_name) AS sku_name, oc1.created_at, (pp.sku_count * oc.quantity) AS egg_count, CAST( TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS DATE ) AS Date, TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS Time_stamp, bn.rate, bn.city_name, fr.cohort_month, fr.month_number, fr.month_name, fr.retained_customers, fr.cohort_customers, fr.retention_rate, rr.retailer_type, CASE WHEN (oc.single_sku_rate * oc.quantity) = 0 THEN \'Promo\' ELSE \'Sales\' END AS order_type, CASE WHEN DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) = cc.cohort_month THEN \'New\' ELSE \'Repeating\' END AS customer_type, CONCAT( oc1.customer_id, \'_\', DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) ) AS unique_customer_month_key, oc1.customer_id AS total_unique_customer, COALESCE(mc.churn_gt_30_lt_90_days, \'No\') AS churn_gt_30_lt_90_days, COALESCE(mc.churn_gt_90_days, \'No\') AS churn_gt_90_days, mc.next_order_date, mc.days_between_orders, mcp.churned_customers_30_90, mcp.churned_customers_90_plus, mcp.total_customers, mcp.churn_pct_30_90, mcp.churn_pct_90_plus, CASE WHEN UPPER(CONCAT(pp.sku_count, pp.short_name)) LIKE \'%HG%\' THEN \'Bread\' WHEN UPPER(CONCAT(pp.sku_count, pp.short_name)) LIKE \'%B%\' AND UPPER(CONCAT(pp.sku_count, pp.short_name)) NOT LIKE \'%W%\' THEN \'Brown\' WHEN UPPER(CONCAT(pp.sku_count, pp.short_name)) LIKE \'%W%\' AND UPPER(CONCAT(pp.sku_count, pp.short_name)) NOT LIKE \'%B%\' THEN \'White\' ELSE \'Mixed\' END AS Product_Type, cet.customer_product_type, CASE WHEN TRY_TO_NUMBER( REGEXP_SUBSTR( CONCAT(pp.sku_count, pp.short_name), \'[0-9]+\' ) ) <= 10 THEN \'Small\' ELSE \'Large\' END AS Egg_Size_Category FROM eggozdb.maplemonk.my_sql_order_cmsorderline oc LEFT JOIN eggozdb.maplemonk.my_sql_order_cmsorder oc1 ON oc.cms_order_id = oc1.id LEFT JOIN eggozdb.maplemonk.my_sql_product_product pp ON pp.id = oc.product_id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_cmscustomer rc ON oc1.customer_id = rc.id LEFT JOIN eggozdb.maplemonk.my_sql_retailer_retailer rr ON oc1.retailer_id = rr.id LEFT JOIN customer_cohort cc ON oc1.customer_id = cc.customer_id AND oc1.retailer_id = cc.retailer_id LEFT JOIN final_retention fr ON cc.cohort_month = fr.cohort_month AND cc.retailer_id = fr.retailer_id AND DATEDIFF( MONTH, cc.cohort_month, DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) ) = fr.month_number LEFT JOIN eggozdb.maplemonk.my_sql_base_neccrates bn ON CAST( TIMESTAMPADD(MINUTE, 330, oc1.created_at) AS DATE ) = bn.date AND bn.city_name = \'Barwala\' LEFT JOIN monthly_churn mc ON oc1.customer_id = mc.customer_id AND oc1.retailer_id = mc.retailer_id AND DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) = mc.reporting_month LEFT JOIN monthly_churn_pct mcp ON oc1.retailer_id = mcp.retailer_id AND DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) = mcp.reporting_month LEFT JOIN customer_egg_type cet ON oc1.customer_id = cet.customer_id AND oc1.retailer_id = cet.retailer_id AND DATE_TRUNC( \'MONTH\', TIMESTAMPADD(MINUTE, 330, oc1.created_at) ) = cet.order_month WHERE rr.retailer_type = \'Coco\';",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            